export const EXERCISES = RAW.map((e) => ({
  ...DEFAULTS,
  ...e,
  weighted: (e.needs || []).some((n) => n === 'hanteln' || n === 'kettlebell'),
}));

export const EX = Object.fromEntries(EXERCISES.map((e) => [e.id, e]));

// Kurzname für Sprachansagen (ohne Klammerzusatz).
export function spokenName(ex) {
  return ex.name.replace(/\s*\(.*?\)\s*/g, ' ').trim();
}
